package dev.rscreatebridge.compat.ponder;

import dev.rscreatebridge.RSCreateBridge;

import net.createmod.ponder.api.registration.PonderPlugin;
import net.createmod.ponder.api.registration.PonderSceneRegistrationHelper;
import net.createmod.ponder.foundation.PonderIndex;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;

/**
 * Ponder scenes (hold W over the item): how to set up the Crafter Interface and the assembly stations.
 * The structures live in {@code assets/rscreatebridge/ponder/} and are generated by the testkit
 * ({@code PonderStructureExport}); the texts are in the lang files ({@code rscreatebridge.ponder.*}).
 * Registered on the client only, from {@link RSCreateBridge}.
 */
public final class BridgePonderPlugin implements PonderPlugin {

    public static void clientSetup(final FMLClientSetupEvent event) {
        PonderIndex.addPlugin(new BridgePonderPlugin());
    }

    @Override
    public String getModId() {
        return RSCreateBridge.MOD_ID;
    }

    @Override
    public void registerScenes(final PonderSceneRegistrationHelper<ResourceLocation> helper) {
        helper.forComponents(id("crafter_interface"))
            .addStoryBoard("crafter_interface", BridgePonderScenes::crafterInterface);
        helper.forComponents(id("assembly_controller"), id("assembly_port"))
            .addStoryBoard("assembly_depot", BridgePonderScenes::depotStation)
            .addStoryBoard("assembly_basin", BridgePonderScenes::basinStation);
    }

    private static ResourceLocation id(final String path) {
        return ResourceLocation.fromNamespaceAndPath(RSCreateBridge.MOD_ID, path);
    }
}
